import { useState, useCallback } from "react";
import "./onboarding.css";
import onboardingCss from "./onboarding.css?inline";
import type {
  OnboardingNewAnswersType,
  OnboardingNewPropsType,
  StageIdType,
} from "./types";
import { FLOW_STAGES, INITIAL_LOADING_TEXTS, getStageProcessingTexts } from "./constants";
import { ProcessingStage } from "./partials/ProcessingStage";
import { ChoiceQuestions } from "./partials/ChoiceQuestions";
import { BrandColor } from "./partials/BrandColor";
import { StylePreset } from "./partials/StylePreset";
import { ToggleGrid } from "./partials/ToggleGrid";
import { CompleteStage } from "./partials/CompleteStage";
import {
  BlockStack,
  Box,
  Button,
  InlineStack,
  ProgressBar,
  Text,
  Transition,
} from "@xco-agency/corex-ui";

type ViewStateType = "initial_loading" | "question" | "save_processing" | "complete";

function getStageValidity(
  stageId: StageIdType,
  answers: OnboardingNewAnswersType,
): boolean {
  if (stageId === "volume") {
    return !!answers.volume;
  }
  return true;
}

export function OnboardingNew({
  onGoToDashboard,
  onRestart,
  initialAnswers = {},
  initialCompletedStages = [],
  onSaveStage,
}: OnboardingNewPropsType) {
  const initialCompletedSet = new Set<StageIdType>(initialCompletedStages);
  const allInitiallyComplete =
    FLOW_STAGES.length > 0 && FLOW_STAGES.every((s) => initialCompletedSet.has(s.id));

  // Determine starting index: first incomplete stage
  const firstIncompleteIdx = FLOW_STAGES.findIndex((s) => !initialCompletedSet.has(s.id));
  const startingStageIdx = firstIncompleteIdx >= 0 ? firstIncompleteIdx : 0;

  const [viewState, setViewState] = useState<ViewStateType>(
    allInitiallyComplete ? "complete" : "initial_loading",
  );
  const [stageIndex, setStageIndex] = useState<number>(startingStageIdx);
  const [answers, setAnswers] = useState<OnboardingNewAnswersType>(initialAnswers);
  const [completedStages, setCompletedStages] =
    useState<Set<StageIdType>>(initialCompletedSet);
  const [processingTexts, setProcessingTexts] = useState<string[]>(INITIAL_LOADING_TEXTS);
  const [leaving, setLeaving] = useState(false);

  const currentStage = FLOW_STAGES[stageIndex] || FLOW_STAGES[0]!;
  const canGoBack = stageIndex > 0;
  const isValid = getStageValidity(currentStage.id, answers);

  const handleInitialLoadingDone = useCallback(() => {
    setLeaving(true);
    setTimeout(() => {
      setViewState("question");
      setLeaving(false);
    }, 250);
  }, []);

  const handleContinue = async () => {
    if (!currentStage) return;

    // Call onSaveStage if provided
    const currentAnswer = answers[currentStage.id];
    if (onSaveStage) {
      await onSaveStage(currentStage.id, currentAnswer);
    }

    // Mark current stage as completed
    const nextCompleted = new Set(completedStages);
    nextCompleted.add(currentStage.id);
    setCompletedStages(nextCompleted);

    // Compute contextual dynamic loading texts based on selection
    const texts = getStageProcessingTexts(currentStage.id, answers);
    setProcessingTexts(texts);

    // Transition to save processing
    setLeaving(true);
    setTimeout(() => {
      setViewState("save_processing");
      setLeaving(false);
    }, 250);
  };

  const handleSaveProcessingDone = useCallback(() => {
    // Find next incomplete stage after current stageIndex
    const nextIdx = FLOW_STAGES.findIndex(
      (s, idx) => idx > stageIndex && !completedStages.has(s.id),
    );

    setLeaving(true);
    setTimeout(() => {
      if (nextIdx !== -1) {
        setStageIndex(nextIdx);
        setViewState("question");
      } else {
        // If no subsequent incomplete stage, check if any earlier stage is still incomplete
        const anyIncompleteIdx = FLOW_STAGES.findIndex(
          (s) => !completedStages.has(s.id) && s.id !== currentStage.id,
        );
        if (anyIncompleteIdx !== -1) {
          setStageIndex(anyIncompleteIdx);
          setViewState("question");
        } else {
          setViewState("complete");
        }
      }
      setLeaving(false);
    }, 250);
  }, [stageIndex, completedStages, currentStage?.id]);

  const handleBack = () => {
    if (stageIndex > 0) {
      setLeaving(true);
      setTimeout(() => {
        setStageIndex((i) => i - 1);
        setViewState("question");
        setLeaving(false);
      }, 250);
    }
  };

  const handleReset = () => {
    setAnswers(initialAnswers);
    setCompletedStages(new Set());
    setStageIndex(0);
    setProcessingTexts(INITIAL_LOADING_TEXTS);
    setViewState("initial_loading");
    if (onRestart) onRestart();
  };

  const totalSteps = FLOW_STAGES.length;
  const shownStep = viewState === "complete" ? totalSteps : stageIndex + 1;
  const progressPct =
    viewState === "complete" ? 100 : (completedStages.size / totalSteps) * 100;
  const showProgress = viewState !== "complete";

  return (
    <BlockStack inlineSize="100%" minBlockSize="760px" alignItems="center" padding="base">
      <style dangerouslySetInnerHTML={{ __html: onboardingCss }} />

      {showProgress && (
        <InlineStack alignItems="center" gap="base">
          <Box inlineSize="90px">
            <ProgressBar progress={progressPct} size="xs" tone="success" />
          </Box>
          <Text color="subdued" variant="small">
            Step {shownStep} of {totalSteps}
          </Text>
        </InlineStack>
      )}

      <BlockStack
        flex={1}
        gap="base"
        alignItems="center"
        justifyContent="center"
        inlineSize="100%"
        maxInlineSize="1200px"
      >
        <Box inlineSize="100%">
          <Transition
            reverse
            key={`${viewState}-${stageIndex}`}
            animate="fade-up"
            leaving={leaving}
            inlineSize="100%"
            display="flex"
            flexDirection="column"
            alignItems="center"
          >
            {viewState === "initial_loading" && (
              <ProcessingStage
                texts={INITIAL_LOADING_TEXTS}
                onDone={handleInitialLoadingDone}
              />
            )}

            {viewState === "save_processing" && (
              <ProcessingStage
                texts={processingTexts}
                onDone={handleSaveProcessingDone}
              />
            )}

            {viewState === "question" && (
              <BlockStack gap="large" inlineSize="100%" alignItems="center">
                {currentStage.id === "volume" && (
                  <ChoiceQuestions answers={answers} setAnswers={setAnswers} />
                )}
                {currentStage.id === "brand" && (
                  <BrandColor answers={answers} setAnswers={setAnswers} />
                )}
                {currentStage.id === "cartStyle" && (
                  <StylePreset answers={answers} setAnswers={setAnswers} />
                )}
                {currentStage.id === "addons" && (
                  <ToggleGrid answers={answers} setAnswers={setAnswers} />
                )}

                <InlineStack
                  gap="base"
                  inlineSize="100%"
                  maxInlineSize="420px"
                  alignItems="center"
                >
                  {canGoBack && (
                    <Button variant="tertiary" onClick={handleBack} icon="arrow-left">
                      Back
                    </Button>
                  )}
                  <Button
                    variant="primary"
                    inlineSize="fill"
                    disabled={!isValid}
                    onClick={handleContinue}
                  >
                    Continue
                  </Button>
                </InlineStack>

                <Text color="subdued">
                  * All configuration are fully customizable anytime from the Hub.
                </Text>
              </BlockStack>
            )}

            {viewState === "complete" && (
              <CompleteStage onRestart={handleReset} onGoToDashboard={onGoToDashboard} />
            )}
          </Transition>
        </Box>
      </BlockStack>
    </BlockStack>
  );
}

export default OnboardingNew;

/* ==========================================================================
   Corex UI - Storefront Cart Drawer Simulation Styles
   Features: Free shipping progress bar, announcement ticker, cart countdown timer,
             rich item details, 1-click upsell, promo input, shipping protection,
             trust badges, and 4 distinct visual presets.
   ========================================================================== */

.cart {
  --cart-primary: #008060;
  --cart-secondary: #1a1a1a;
  --cart-accent: #e8b84b;
  --cart-background: #ffffff;
  --cart-surface: #f6f6f7;
  --cart-border: color-mix(in srgb, var(--cart-secondary) 12%, transparent);
  --cart-text-subdued: color-mix(in srgb, var(--cart-secondary) 58%, transparent);

  width: 100%;
  min-height: 100%;
  box-sizing: border-box;

  display: flex;
  flex-direction: column;

  overflow-x: hidden;
  overflow-y: auto;

  background: var(--cart-background);
  color: var(--cart-secondary);

  font-family:
    Inter,
    ui-sans-serif,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
  -webkit-font-smoothing: antialiased;

  box-shadow: 0 20px 60px rgb(0 0 0 / 12%);
}

/* --------------------------------
   Announcement / Ticker Banner
-------------------------------- */

.announcementBanner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;

  padding: 8px 16px;

  background: color-mix(in srgb, var(--cart-primary) 10%, transparent);
  color: var(--cart-primary);

  font-size: 11px;
  font-weight: 600;
  text-align: center;
  letter-spacing: 0.01em;
}

.announcementBanner span {
  display: inline-flex;
  align-items: center;
}

/* --------------------------------
   Header & Cart Reservation Timer
-------------------------------- */

.header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  padding: 22px 22px 14px;
}

.headerTitleGroup {
  display: flex;
  flex-direction: column;
}

.eyebrow {
  display: block;

  color: var(--cart-text-subdued);

  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.title {
  margin: 4px 0 0;

  color: var(--cart-secondary);

  font-size: 22px;
  line-height: 1.15;
  letter-spacing: -0.035em;
  font-weight: 700;
}

.headerActions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.count {
  display: grid;
  place-items: center;

  min-width: 26px;
  height: 26px;

  border-radius: 50%;

  background: color-mix(in srgb, var(--cart-secondary) 8%, transparent);
  color: var(--cart-secondary);

  font-size: 11px;
  font-weight: 700;
}

/* Cart countdown reservation pill */
.cartTimer {
  display: flex;
  align-items: center;
  gap: 6px;

  margin: 0 22px 14px;
  padding: 7px 12px;

  border-radius: 6px;

  background: color-mix(in srgb, var(--cart-accent) 15%, transparent);
  border: 1px solid color-mix(in srgb, var(--cart-accent) 35%, transparent);

  color: var(--cart-secondary);

  font-size: 11px;
  font-weight: 500;
}

.cartTimer strong {
  font-weight: 700;
  color: var(--cart-secondary);
}

.timerIcon {
  display: inline-block;
  font-size: 12px;
}

/* --------------------------------
   Free Shipping Progress Bar
-------------------------------- */

.shippingBar {
  margin: 0 22px 16px;
  padding: 12px 14px;

  border-radius: 8px;

  background: color-mix(in srgb, var(--cart-secondary) 4%, transparent);
  border: 1px solid var(--cart-border);
}

.shippingBarText {
  margin: 0 0 8px;

  color: var(--cart-secondary);

  font-size: 11px;
  line-height: 1.35;
  font-weight: 500;
}

.shippingBarText strong {
  font-weight: 700;
  color: var(--cart-primary);
}

.shippingTrack {
  position: relative;
  width: 100%;
  height: 6px;

  overflow: hidden;

  border-radius: 999px;
  background: color-mix(in srgb, var(--cart-secondary) 10%, transparent);
}

.shippingFill {
  height: 100%;
  border-radius: 999px;
  background: var(--cart-primary);
  transition: width 350ms cubic-bezier(0.16, 1, 0.3, 1);
}

.shippingUnlocked {
  display: flex;
  align-items: center;
  gap: 6px;

  color: var(--cart-primary);

  font-weight: 700;
}

/* --------------------------------
   Items List
-------------------------------- */

.items {
  flex: 1;
  padding: 0 22px;
}

.item {
  display: flex;
  gap: 14px;

  padding: 16px 0;

  border-top: 1px solid var(--cart-border);
}

.productImage {
  width: 76px;
  height: 92px;

  flex: 0 0 76px;

  object-fit: cover;
  border-radius: 6px;

  background: color-mix(in srgb, var(--cart-secondary) 5%, transparent);
}

.itemContent {
  min-width: 0;
  flex: 1;

  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.itemTop {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 8px;
}

.productTitle {
  margin: 0;

  color: var(--cart-secondary);

  font-size: 13px;
  line-height: 1.3;
  font-weight: 600;
}

.productVariant {
  margin: 3px 0 0;

  color: var(--cart-text-subdued);

  font-size: 11px;
}

.itemBadges {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 4px;
}

.saveBadge {
  display: inline-block;

  padding: 2px 6px;

  border-radius: 4px;

  background: color-mix(in srgb, var(--cart-primary) 12%, transparent);
  color: var(--cart-primary);

  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.stockNotice {
  color: #d82c0d;
  font-size: 10px;
  font-weight: 600;
  margin-top: 3px;
}

.remove {
  width: 22px;
  height: 22px;

  padding: 0;

  border: 0;
  background: transparent;

  color: var(--cart-text-subdued);

  cursor: pointer;

  font-size: 18px;
  line-height: 1;

  transition: color 150ms ease;
}

.remove:hover {
  color: #d82c0d;
}

.itemBottom {
  display: flex;
  align-items: center;
  justify-content: space-between;

  margin-top: 12px;
}

.priceGroup {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.itemPrice {
  color: var(--cart-secondary);

  font-size: 13px;
  font-weight: 700;
}

.comparePrice {
  color: var(--cart-text-subdued);

  font-size: 11px;
  text-decoration: line-through;
}

.quantity {
  display: flex;
  align-items: center;

  height: 28px;

  border: 1px solid var(--cart-border);
  border-radius: 4px;
  background: var(--cart-background);
}

.quantity button {
  width: 26px;
  height: 100%;

  display: grid;
  place-items: center;

  border: 0;
  background: transparent;

  color: var(--cart-secondary);

  cursor: pointer;
  font-size: 14px;
  font-weight: 600;

  transition: background 150ms ease;
}

.quantity button:hover:not(:disabled) {
  background: color-mix(in srgb, var(--cart-secondary) 8%, transparent);
}

.quantity button:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.quantity span {
  min-width: 22px;

  text-align: center;

  color: var(--cart-secondary);

  font-size: 11px;
  font-weight: 600;
}

/* --------------------------------
   In-Cart 1-Click Upsell Widget
-------------------------------- */

.upsellSection {
  margin: 16px 0 6px;
  padding: 12px 14px;

  border-radius: 8px;

  background: color-mix(in srgb, var(--cart-secondary) 3%, transparent);
  border: 1px dashed var(--cart-border);
}

.upsellHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}

.upsellTitle {
  margin: 0;

  color: var(--cart-secondary);

  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.upsellBadge {
  font-size: 10px;
  font-weight: 600;
  color: var(--cart-primary);
}

.upsellCard {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.upsellImage {
  width: 44px;
  height: 44px;

  flex: 0 0 44px;

  object-fit: cover;
  border-radius: 6px;
}

.upsellInfo {
  min-width: 0;
  flex: 1;
}

.upsellName {
  margin: 0;

  color: var(--cart-secondary);

  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.upsellPrice {
  margin: 2px 0 0;

  color: var(--cart-text-subdued);

  font-size: 11px;
  font-weight: 600;
}

.upsellPrice strong {
  color: var(--cart-secondary);
}

.upsellBtn {
  padding: 6px 12px;

  border: 1px solid var(--cart-secondary);
  border-radius: 4px;

  background: transparent;
  color: var(--cart-secondary);

  cursor: pointer;

  font-size: 11px;
  font-weight: 700;

  transition: all 150ms ease;
}

.upsellBtn:hover {
  background: var(--cart-secondary);
  color: #ffffff;
}

.upsellBtnAdded {
  background: var(--cart-primary) !important;
  border-color: var(--cart-primary) !important;
  color: #ffffff !important;
}

/* --------------------------------
   Footer & Order Summary
-------------------------------- */

.footer {
  padding: 18px 22px 22px;

  border-top: 1px solid var(--cart-border);
  background: var(--cart-background);
}

.summaryHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;

  color: var(--cart-secondary);

  font-size: 13px;
}

.summaryHeader strong {
  font-size: 15px;
  font-weight: 700;
}

.summaryDetails {
  padding-top: 14px;
}

.summaryRow {
  display: flex;
  align-items: center;
  justify-content: space-between;

  margin-bottom: 9px;

  color: var(--cart-text-subdued);

  font-size: 12px;
}

.protectionLabel {
  display: flex;
  align-items: center;
  gap: 7px;

  color: var(--cart-secondary);
  cursor: pointer;
  user-select: none;
}

.checkbox {
  display: inline-grid;
  place-items: center;

  width: 16px;
  height: 16px;

  border-radius: 3px;
  border: 1px solid var(--cart-primary);

  background: var(--cart-primary);
  color: #fff;

  font-size: 10px;
  font-weight: 700;
  transition: all 150ms ease;
}

.checkboxUnchecked {
  background: transparent;
  border-color: var(--cart-border);
  color: transparent;
}

.info {
  display: inline-grid;
  place-items: center;

  width: 14px;
  height: 14px;

  border: 1px solid color-mix(in srgb, var(--cart-secondary) 30%, transparent);
  border-radius: 50%;

  color: var(--cart-text-subdued);

  font-size: 9px;
  font-weight: 700;
}

.discount {
  color: var(--cart-primary) !important;
  font-weight: 600;
}

/* Promo code input row */
.promoRow {
  display: flex;
  gap: 8px;
  margin: 12px 0;
}

.promoInput {
  flex: 1;
  height: 32px;
  padding: 0 10px;

  border: 1px solid var(--cart-border);
  border-radius: 4px;

  background: transparent;
  color: var(--cart-secondary);

  font-size: 11px;
}

.promoInput:focus {
  outline: none;
  border-color: var(--cart-primary);
}

.promoBtn {
  height: 32px;
  padding: 0 14px;

  border: 0;
  border-radius: 4px;

  background: color-mix(in srgb, var(--cart-secondary) 10%, transparent);
  color: var(--cart-secondary);

  cursor: pointer;
  font-size: 11px;
  font-weight: 600;

  transition: background 150ms ease;
}

.promoBtn:hover {
  background: color-mix(in srgb, var(--cart-secondary) 18%, transparent);
}

.tax {
  margin: 12px 0 0;

  color: var(--cart-text-subdued);

  font-size: 10px;
}

.finalTotal {
  display: flex;
  align-items: center;
  justify-content: space-between;

  margin-top: 14px;
  padding-top: 14px;

  border-top: 1px solid var(--cart-border);

  color: var(--cart-secondary);

  font-size: 13px;
}

.finalTotal strong {
  font-size: 17px;
  font-weight: 800;
}

.checkout {
  display: flex;
  align-items: center;
  justify-content: space-between;

  width: 100%;
  height: 48px;

  margin-top: 16px;
  padding: 0 18px;

  border: 0;
  border-radius: 6px;

  background: var(--cart-primary);
  color: #fff;

  cursor: pointer;

  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.01em;

  transition:
    opacity 150ms ease,
    transform 150ms ease,
    box-shadow 150ms ease;

  box-shadow: 0 4px 14px color-mix(in srgb, var(--cart-primary) 30%, transparent);
}

.checkout:hover {
  opacity: 0.92;
  transform: translateY(-1px);
  box-shadow: 0 6px 18px color-mix(in srgb, var(--cart-primary) 40%, transparent);
}

.checkout:active {
  transform: translateY(0);
}

.continueShopping {
  display: block;

  margin: 11px auto 0;
  padding: 0;

  border: 0;
  background: transparent;

  color: var(--cart-text-subdued);

  cursor: pointer;

  font-size: 11px;
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* Trust badges footer */
.trustFooter {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;

  margin-top: 14px;
  padding-top: 12px;

  border-top: 1px solid color-mix(in srgb, var(--cart-secondary) 7%, transparent);
}

.trustGuarantee {
  display: flex;
  align-items: center;
  gap: 5px;

  color: var(--cart-text-subdued);

  font-size: 10px;
  font-weight: 500;
}

.paymentPills {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.paymentPill {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  padding: 2px 8px;
  height: 18px;

  border-radius: 3px;
  border: 1px solid var(--cart-border);

  background: var(--cart-background);
  color: var(--cart-text-subdued);

  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

/* ==========================================================================
   PRESET 1: MINIMAL
   Aesthetic: Scandinavian, Apple-inspired, clean hairlines, pure typography
   ========================================================================== */

.preset-minimal .cart,
.preset-standard .cart {
  background: #ffffff;
  color: #1a1a1a;
  box-shadow: 0 10px 40px rgb(0 0 0 / 6%);
}

.preset-minimal .title {
  font-weight: 600;
  letter-spacing: -0.025em;
}

.preset-minimal .productImage {
  border-radius: 4px;
}

.preset-minimal .quantity {
  border-radius: 4px;
  border-color: #e5e5e5;
}

.preset-minimal .checkout {
  border-radius: 4px;
  box-shadow: none;
  font-weight: 600;
}

.preset-minimal .upsellSection {
  border-style: solid;
  border-color: #efefef;
  background: #fafafa;
}

.preset-minimal .shippingBar {
  border-color: #ededed;
  background: #fbfbfb;
}

/* ==========================================================================
   PRESET 2: BOLD
   Aesthetic: Dark mode, high contrast, streetwear / sportswear energy
   ========================================================================== */

.preset-bold {
  --cart-background: #111215;
  --cart-surface: #1a1b20;
