import { useState, useEffect } from "react";
import type { Dispatch, SetStateAction } from "react";
import {
  Badge,
  BlockStack,
  Box,
  Button,
  Card,
  ColorField,
  Grid,
  Icon,
  IconTile,
  InlineStack,
  Text,
} from "@xco-agency/corex-ui";
import type { BrandColorsType, OnboardingNewAnswersType } from "../types";
import { DEFAULT_BRAND_COLORS } from "../constants";

export type BrandColorPropsType = {
  answers: OnboardingNewAnswersType;
  setAnswers: Dispatch<SetStateAction<OnboardingNewAnswersType>>;
};

export function BrandColor({ answers, setAnswers }: BrandColorPropsType) {
  const [scanning, setScanning] = useState(false);
  const [scanned, setScanned] = useState(false);

  const colors = answers.brand || DEFAULT_BRAND_COLORS;

  useEffect(() => {
    if (!answers.brand) {
      setAnswers((prev) => ({ ...prev, brand: DEFAULT_BRAND_COLORS }));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const updateColor = (key: keyof BrandColorsType, value: string) => {
    setAnswers((prev) => ({
      ...prev,
      brand: {
        ...(prev.brand || DEFAULT_BRAND_COLORS),
        [key]: value,
        source: "manual",
      },
    }));
  };

  const handleScan = () => {
    setScanning(true);
    setTimeout(() => {
      const detected: BrandColorsType = {
        primary: "#1F6F50",
        secondary: "#10241C",
        accent: "#E8B84B",
        background: "#F2F5F1",
      };
      setAnswers((prev) => ({
        ...prev,
        brand: { ...detected, source: "scan" },
      }));
      setScanning(false);
      setScanned(true);
    }, 1500);
  };

  const order: [keyof BrandColorsType, string][] = [
    ["primary", "Primary"],
    ["secondary", "Secondary"],
    ["accent", "Accent"],
    ["background", "Background"],
  ];

  return (
    <Card heading="Add your brand colors">
      <BlockStack gap="base">
        <Text color="subdued">
          We&apos;ll use these across your cart drawer, badges, and upsell widgets.
        </Text>

        <Box
          padding="base"
          borderRadius="base"
          borderWidth="0165"
          borderColor="border"
          background="bg-surface-secondary"
        >
          <InlineStack justifyContent="space-between" alignItems="center" gap="base" wrap>
            <InlineStack gap="base" alignItems="center">
              <IconTile tone="success" size="lg" borderRadius="full">
                <Icon type="store" tone="success" />
              </IconTile>
              <BlockStack gap="small-400">
                <Text variant="bodyMd" fontWeight="semibold">
                  Scan your store for branding
                </Text>
                <Text variant="bodySm" color="subdued">
                  We&apos;ll analyze your storefront and match your colors automatically.
                </Text>
              </BlockStack>
            </InlineStack>

            <Button variant="primary" loading={scanning} onClick={handleScan}>
              {scanned ? "Scan again" : "Scan now"}
            </Button>
          </InlineStack>
        </Box>

        {scanned && (
          <Box paddingBlock="small-200">
            <InlineStack gap="small-200" alignItems="center">
              <Icon type="check" tone="success" />
              <Text variant="bodySm" color="success" fontWeight="semibold">
                Colors updated from your store
              </Text>
            </InlineStack>
          </Box>
        )}

        <Grid columns={{ xs: 2, sm: 4 }} gap="base">
          {order.map(([key, label]) => (
            <Grid.Item key={key}>
              <ColorField
                label={label}
                value={colors[key] || "#000000"}
                onChange={(val: string) => updateColor(key, val)}
              />
            </Grid.Item>
          ))}
        </Grid>

        <Box
          padding="base"
          borderRadius="base"
          borderWidth="0165"
          borderColor="border"
          background="bg-surface-secondary"
        >
          <BlockStack gap="small">
            <Text variant="bodySm" color="subdued" fontWeight="semibold">
              Live preview
            </Text>
            <InlineStack gap="base" alignItems="center">
              <Button variant="primary">Add to cart</Button>
              <Badge tone="success">Sale</Badge>
            </InlineStack>
          </BlockStack>
        </Box>
      </BlockStack>
    </Card>
  );
}

import { useState } from "react";
import type { BrandColorsType, CartPresetIdType } from "../types";
import styles from "../cart-variants.module.css";

export interface CartDrawerItemType {
  id: string;
  title: string;
  variant?: string;
  price: number;
  compareAtPrice?: number;
  saveBadge?: string;
  stockNotice?: string;
  quantity: number;
  image: string;
}

export interface CartDrawerContentPropsType {
  preset: CartPresetIdType;
  brand: BrandColorsType;
  currency?: string;
  interactive?: boolean;
  onClose?: () => void;
}

const INITIAL_ITEMS: CartDrawerItemType[] = [
  {
    id: "1",
    title: "Essential Oversized Tee",
    variant: "Black / Large",
    price: 29,
    compareAtPrice: 36,
    saveBadge: "Save 20%",
    stockNotice: "Only 3 left in stock",
    quantity: 1,
    image: "https://images.unsplash.com/photo-1521572163474-6864f9cf17ab?w=400&q=80",
  },
  {
    id: "2",
    title: "Relaxed Everyday Pants",
    variant: "Stone / 32",
    price: 64,
    quantity: 1,
    image: "https://images.unsplash.com/photo-1624378439575-d8705ad7ae80?w=400&q=80",
  },
];

const UPSELL_ITEM: CartDrawerItemType = {
  id: "upsell-beanie",
  title: "Merino Wool Beanie",
  variant: "Charcoal / One Size",
  price: 18,
  compareAtPrice: 24,
  quantity: 1,
  image: "https://images.unsplash.com/photo-1576871337622-98d48d1cf531?w=400&q=80",
};

export function CartDrawerContent({
  preset,
  brand,
  currency = "MAD",
  interactive = true,
  onClose,
}: CartDrawerContentPropsType) {
  const [items, setItems] = useState<CartDrawerItemType[]>(INITIAL_ITEMS);
  const [protectionEnabled, setProtectionEnabled] = useState(true);
  const [upsellAdded, setUpsellAdded] = useState(false);
  const [promoCode, setPromoCode] = useState("");
  const [promoApplied, setPromoApplied] = useState(true);
  const [checkoutFeedback, setCheckoutFeedback] = useState(false);

  const subtotal = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const discount = promoApplied ? 5 : 0;
  const protectionFee = protectionEnabled ? 2.99 : 0;
  const estimatedTotal = Math.max(0, subtotal - discount + protectionFee);

  // Free shipping goal threshold at 100
  const freeShippingThreshold = 100;
  const remainingForFreeShipping = Math.max(0, freeShippingThreshold - subtotal);
  const shippingProgressPct = Math.min(
    100,
    Math.round((subtotal / freeShippingThreshold) * 100),
  );
  const isFreeShippingUnlocked = remainingForFreeShipping === 0;

  const handleQuantityChange = (id: string, delta: number) => {
    if (!interactive) return;
    setItems((prev) =>
      prev
        .map((item) => {
          if (item.id === id) {
            const nextQty = Math.max(1, item.quantity + delta);
            return { ...item, quantity: nextQty };
          }
          return item;
        })
        .filter((item) => item.quantity > 0),
    );
  };

  const handleRemove = (id: string) => {
    if (!interactive) return;
    setItems((prev) => prev.filter((item) => item.id !== id));
    if (id === UPSELL_ITEM.id) {
      setUpsellAdded(false);
    }
  };

  const handleToggleUpsell = () => {
    if (!interactive) return;
    if (upsellAdded) {
      setItems((prev) => prev.filter((item) => item.id !== UPSELL_ITEM.id));
      setUpsellAdded(false);
    } else {
      setItems((prev) => [...prev, UPSELL_ITEM]);
      setUpsellAdded(true);
    }
  };

  const handleApplyPromo = () => {
    if (!interactive) return;
    if (promoCode.trim().length > 0) {
      setPromoApplied(true);
    }
  };

  const handleCheckout = () => {
    if (!interactive) return;
    setCheckoutFeedback(true);
    setTimeout(() => setCheckoutFeedback(false), 2200);
  };

  const isBold = preset === "bold";
  const resolvedBg = isBold
    ? "#111215"
    : preset === "editorial"
      ? "#fbf9f6"
      : preset === "minimal"
        ? "#ffffff"
        : brand.background || "#ffffff";

  const resolvedText = isBold ? "#ffffff" : brand.secondary || "#1a1a1a";
  const resolvedPrimary = isBold
    ? "#008060"
    : brand.primary || (preset === "editorial" ? "#111215" : "#008060");
  const resolvedAccent = brand.accent || "#e8b84b";
  const resolvedSurface = isBold ? "#1a1b20" : "#f6f6f7";

  return (
    <div
      className={`${styles.cart} ${styles[`preset-${preset}`]} ${
        !interactive ? styles.cartPreviewMode : ""
      }`}
      style={
        {
          "--cart-primary": resolvedPrimary,
          "--cart-secondary": resolvedText,
          "--cart-accent": resolvedAccent,
          "--cart-background": resolvedBg,
          "--cart-surface": resolvedSurface,
        } as React.CSSProperties
      }
    >
      {/* 1. Contextual Announcement Banner */}
      <div className={styles.announcementBanner}>
        <span>
          {preset === "editorial"
            ? "✦ Complimentary signature gift packaging on all orders"
            : preset === "bold"
              ? "⚡️ EXCLUSIVE OFFER: Free standard express delivery unlocked"
              : preset === "rounded"
                ? "✨ Free gift automatically included with orders over 80 MAD!"
                : "Limited Release • Free 30-day domestic returns"}
        </span>
      </div>

      {/* 2. Header */}
      <header className={styles.header}>
        <div className={styles.headerTitleGroup}>
          <span className={styles.eyebrow}>
            {preset === "editorial" ? "Your Cart Collection" : "Your Selection"}
          </span>
          <h1 className={styles.title}>Your Cart</h1>
        </div>

        <div className={styles.headerActions}>
          <span className={styles.count}>{items.length}</span>
          {onClose && (
            <button
              type="button"
              className={styles.remove}
              onClick={onClose}
              aria-label="Close cart drawer"
            >
              ×
            </button>
          )}
        </div>
      </header>

      {/* 3. Cart Reservation Urgency Timer */}
      <div className={styles.cartTimer}>
        <span className={styles.timerIcon}>⏱</span>
        <span>
          High demand: items reserved for <strong>09:42</strong>
        </span>
      </div>

      {/* 4. Free Shipping Tier Progress Bar */}
      <div className={styles.shippingBar}>
        <div className={styles.shippingBarText}>
          {isFreeShippingUnlocked ? (
            <span className={styles.shippingUnlocked}>
              🎉 You unlocked <strong>FREE Shipping</strong>!
            </span>
          ) : (
            <span>
              Add{" "}
              <strong>
                {currency} {remainingForFreeShipping.toFixed(2)}
              </strong>{" "}
              more to unlock <strong>FREE Shipping</strong>
            </span>
          )}
        </div>
        <div className={styles.shippingTrack}>
          <div
            className={styles.shippingFill}
            style={{ width: `${shippingProgressPct}%` }}
          />
        </div>
      </div>

      {/* 5. Cart Items */}
      <main className={styles.items}>
        {items.length === 0 ? (
          <div style={{ textAlign: "center", padding: "40px 10px" }}>
            <p style={{ margin: "0 0 8px", fontWeight: 600 }}>Your cart is empty</p>
            <p style={{ margin: 0, fontSize: "12px", opacity: 0.6 }}>
              Add trending products to test this drawer.
            </p>
          </div>
        ) : (
          (interactive ? items : items.slice(0, 1)).map((item) => (
            <article className={styles.item} key={item.id}>
              <img className={styles.productImage} src={item.image} alt={item.title} />

              <div className={styles.itemContent}>
                <div className={styles.itemTop}>
                  <div>
                    <h2 className={styles.productTitle}>{item.title}</h2>
                    {item.variant && (
                      <p className={styles.productVariant}>{item.variant}</p>
                    )}
                    {(item.saveBadge || item.stockNotice) && (
                      <div className={styles.itemBadges}>
                        {item.saveBadge && (
                          <span className={styles.saveBadge}>{item.saveBadge}</span>
                        )}
                        {item.stockNotice && (
                          <span className={styles.stockNotice}>{item.stockNotice}</span>
                        )}
                      </div>
                    )}
                  </div>

                  <button
                    type="button"
                    className={styles.remove}
                    onClick={() => handleRemove(item.id)}
                    aria-label={`Remove ${item.title}`}
                  >
                    ×
                  </button>
                </div>

                <div className={styles.itemBottom}>
                  <div className={styles.quantity}>
                    <button
                      type="button"
                      onClick={() => handleQuantityChange(item.id, -1)}
                      disabled={item.quantity <= 1}
                      aria-label="Decrease quantity"
                    >
                      −
                    </button>
                    <span>{item.quantity}</span>
                    <button
                      type="button"
                      onClick={() => handleQuantityChange(item.id, 1)}
                      aria-label="Increase quantity"
                    >
                      +
                    </button>
                  </div>

                  <div className={styles.priceGroup}>
                    {item.compareAtPrice && (
                      <span className={styles.comparePrice}>
                        {currency} {(item.compareAtPrice * item.quantity).toFixed(2)}
                      </span>
                    )}
                    <strong className={styles.itemPrice}>
                      {currency} {(item.price * item.quantity).toFixed(2)}
                    </strong>
                  </div>
                </div>
              </div>
            </article>
          ))
        )}

        {/* 6. In-Cart 1-Click Upsell Recommendation */}
        <section className={styles.upsellSection}>
          <div className={styles.upsellHeader}>
            <h3 className={styles.upsellTitle}>Frequently Added Together</h3>
            <span className={styles.upsellBadge}>⚡️ 25% Off</span>
          </div>
          <div className={styles.upsellCard}>
            <img
              className={styles.upsellImage}
              src={UPSELL_ITEM.image}
              alt={UPSELL_ITEM.title}
            />
            <div className={styles.upsellInfo}>
              <p className={styles.upsellName}>{UPSELL_ITEM.title}</p>
              <p className={styles.upsellPrice}>
                <strong>
                  {currency} {UPSELL_ITEM.price.toFixed(2)}
                </strong>{" "}
                <span className={styles.comparePrice}>
                  {currency} {UPSELL_ITEM.compareAtPrice?.toFixed(2)}
                </span>
              </p>
            </div>
            <button
              type="button"
              className={`${styles.upsellBtn} ${upsellAdded ? styles.upsellBtnAdded : ""}`}
              onClick={handleToggleUpsell}
            >
              {upsellAdded ? "✓ Added" : "+ Add"}
            </button>
          </div>
        </section>
      </main>

      {/* 7. Footer & Order Summary */}
      <footer className={styles.footer}>
        <div className={styles.summary}>
          <div className={styles.summaryHeader}>
            <span>Estimated Total</span>
            <strong>
              {currency} {estimatedTotal.toFixed(2)}
            </strong>
          </div>

          <div className={styles.summaryDetails}>
            <div className={styles.summaryRow}>
              <span>Subtotal</span>
              <span>
                {currency} {subtotal.toFixed(2)}
              </span>
            </div>

            {/* Shipping Protection Add-on */}
            <div className={styles.summaryRow}>
              <span
                className={styles.protectionLabel}
                onClick={() => interactive && setProtectionEnabled(!protectionEnabled)}
              >
                <span
                  className={`${styles.checkbox} ${!protectionEnabled ? styles.checkboxUnchecked : ""}`}
                >
                  ✓
                </span>
                <span>Package Protection</span>
                <span
                  className={styles.info}
                  title="Guaranteed protection against loss, theft or damage during transit."
                >
                  i
                </span>
              </span>
              <span>
                +{currency} {protectionFee.toFixed(2)}
              </span>
            </div>

            {/* Promo Code Discount */}
            {promoApplied && (
              <div className={styles.summaryRow}>
                <span>Discount (WELCOME5)</span>
                <span className={styles.discount}>
                  −{currency} {discount.toFixed(2)}
                </span>
              </div>
            )}

            <div className={styles.summaryRow}>
              <span>Standard Shipping</span>
              <span className={isFreeShippingUnlocked ? styles.discount : ""}>
                {isFreeShippingUnlocked ? "FREE" : `${currency} 15.00`}
              </span>
            </div>

            {/* Promo Code Input Field */}
            <div className={styles.promoRow}>
              <input
                className={styles.promoInput}
                type="text"
                placeholder="Discount code or gift card"
                value={promoCode}
                onChange={(e) => setPromoCode(e.target.value)}
              />
              <button
                type="button"
                className={styles.promoBtn}
                onClick={handleApplyPromo}
              >
                Apply
              </button>
            </div>

            <p className={styles.tax}>Taxes calculated at checkout</p>

            <div className={styles.finalTotal}>
              <span>Estimated Total</span>
              <strong>
                {currency} {estimatedTotal.toFixed(2)}
              </strong>
            </div>
          </div>
        </div>

        {/* Primary Checkout CTA */}
        <button type="button" className={styles.checkout} onClick={handleCheckout}>
          <span>{checkoutFeedback ? "Processing..." : "🔒 Secure Checkout"}</span>
          <span>
            {currency} {estimatedTotal.toFixed(2)} →
          </span>
        </button>

        {onClose && (
          <button
            type="button"
            className={styles.continueShopping}
            onClick={onClose}
          >
            Continue shopping
          </button>
        )}

        {/* Trust Badges & Payment Methods */}
        <div className={styles.trustFooter}>
          <div className={styles.trustGuarantee}>
            <span>🛡️</span>
            <span>256-Bit SSL Encrypted • 30-Day Money-Back Guarantee</span>
          </div>
          <div className={styles.paymentPills}>
            <span className={styles.paymentPill}>Apple Pay</span>
            <span className={styles.paymentPill}>Shop Pay</span>
            <span className={styles.paymentPill}>GPay</span>
            <span className={styles.paymentPill}>Visa</span>
            <span className={styles.paymentPill}>Mastercard</span>
          </div>
        </div>
      </footer>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { Box } from "@xco-agency/corex-ui";
import type { BrandColorsType, CartPresetIdType } from "../types";
import { CartDrawerContent } from "./CartDrawerContent";
import styles from "../cart-variants.module.css";

export interface CartIframePropsType {
  preset: CartPresetIdType;
  brand: BrandColorsType;
  currency?: string;
  mode?: "preview" | "full";
  interactive?: boolean;
  onClose?: () => void;
}

export function CartIframe({
  preset,
  brand,
  currency = "MAD",
  mode = "preview",
  interactive = mode === "full",
  onClose,
}: CartIframePropsType) {
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const scaleWrapperRef = useRef<HTMLDivElement>(null);
  const [mountNode, setMountNode] = useState<HTMLElement | null>(null);

  // Initialize iframe document and synchronize stylesheet tags from host document
  useEffect(() => {
    const iframe = iframeRef.current;
    if (!iframe) return;

    const setupIframe = () => {
      const doc = iframe.contentDocument || iframe.contentWindow?.document;
      if (!doc) return;

      if (!doc.getElementById("cart-root")) {
        doc.open();
        doc.write(`
          <!DOCTYPE html>
          <html lang="en">
            <head>
              <meta charset="utf-8" />
              <meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1" />
              <base href="${typeof window !== "undefined" ? window.location.origin : ""}/" />
              <link rel="preconnect" href="https://fonts.googleapis.com" />
              <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
              <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;1,400&display=swap" rel="stylesheet" />
              <style>
                *, *::before, *::after {
                  box-sizing: border-box;
                }
                html, body {
                  margin: 0;
                  padding: 0;
                  width: 100%;
                  min-height: 100%;
                  background: transparent;
                  -webkit-font-smoothing: antialiased;
                  overflow-x: hidden;
                }
                /* Custom slim scrollbar */
                ::-webkit-scrollbar {
                  width: 5px;
                }
                ::-webkit-scrollbar-track {
                  background: transparent;
                }
                ::-webkit-scrollbar-thumb {
                  background: rgba(0, 0, 0, 0.15);
                  border-radius: 999px;
                }
                ::-webkit-scrollbar-thumb:hover {
                  background: rgba(0, 0, 0, 0.25);
                }
              </style>
            </head>
            <body>
              <div id="cart-root" style="width: 100%; min-height: 100%;"></div>
            </body>
          </html>
        `);
        doc.close();
      }

      // Sync existing host styles into iframe
      const syncStyles = () => {
        const parentStyles = document.querySelectorAll("style, link[rel='stylesheet']");
        parentStyles.forEach((el) => {
          if (el.tagName === "LINK") {
            const href = (el as HTMLLinkElement).href;
            if (href.includes("fonts.googleapis.com")) return;
            if (doc.querySelector(`link[href="${href}"]`)) return;
            const link = doc.createElement("link");
            link.rel = "stylesheet";
            link.href = href;
            doc.head.appendChild(link);
          } else if (el.tagName === "STYLE") {
            const viteId = el.getAttribute("data-vite-dev-id");
            if (viteId && doc.querySelector(`style[data-vite-dev-id="${viteId}"]`)) return;
            const style = doc.createElement("style");
            if (viteId) style.setAttribute("data-vite-dev-id", viteId);
            style.textContent = el.textContent;
            doc.head.appendChild(style);
          }
        });
      };

      syncStyles();

      // Mirror new styles dynamically (HMR or asynchronous CSS)
      const observer = new MutationObserver(() => syncStyles());
      observer.observe(document.head, { childList: true, subtree: true });

      const root = doc.getElementById("cart-root");
      if (root) {
        setMountNode(root);
      }
    };

    if (iframe.contentDocument?.readyState === "complete") {
      setupIframe();
    } else {
      iframe.addEventListener("load", setupIframe, { once: true });
    }
  }, []);

  // Compute responsive miniature scale for preview mode based on card container width
  useEffect(() => {
    if (mode !== "preview") return;
    const updateScale = () => {
      if (containerRef.current && scaleWrapperRef.current) {
        const containerWidth = containerRef.current.clientWidth;
        if (containerWidth > 0) {
          // Internal virtual mobile viewport is 380px
          const calculatedScale = Math.min(0.55, Math.max(0.38, containerWidth / 380));
          scaleWrapperRef.current.style.setProperty(
            "--preview-scale",
            String(calculatedScale),
          );
        }
      }
    };

    updateScale();
    window.addEventListener("resize", updateScale);
    return () => window.removeEventListener("resize", updateScale);
  }, [mode]);

  if (mode === "preview") {
    return (
      <Box
        position="relative"
        inlineSize="100%"
        className={styles.miniPhoneContainer}
      >
        <Box
          position="relative"
          className={`${styles.miniPhoneChassis} ${
            preset === "bold" ? styles.miniPhoneChassisBold : ""
          }`}
        >
          <Box className={styles.miniPhoneSpeaker} />
          <Box className={styles.miniPhoneScreen}>
            <iframe
              ref={iframeRef}
              title={`Cart Drawer Preview - ${preset}`}
              className={styles.miniPhoneIframe}
              tabIndex={-1}
            />
          </Box>
        </Box>
        {mountNode
          ? createPortal(
              <CartDrawerContent
                preset={preset}
                brand={brand}
                currency={currency}
                interactive={false}
              />,
              mountNode,
            )
          : null}
      </Box>
    );
  }

  // Full-size interactive viewport (for modal)
  return (
    <Box
      inlineSize="100%"
      blockSize="100%"
      position="relative"
      background="transparent"
      overflow="hidden"
    >
      <iframe
        ref={iframeRef}
        title={`Full Cart Drawer Preview - ${preset}`}
        className={styles.fullIframe}
      />
      {mountNode
        ? createPortal(
            <CartDrawerContent
              preset={preset}
              brand={brand}
              currency={currency}
              interactive={interactive}
              onClose={onClose}
            />,
            mountNode,
          )
        : null}
    </Box>
  );
}

import { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import {
  BlockStack,
  Box,
  Button,
  Clickable,
  InlineStack,
  Text,
  Transition,
} from "@xco-agency/corex-ui";
import type { BrandColorsType, CartPresetIdType } from "../types";
import { CartIframe } from "./CartIframe";
import styles from "../cart-variants.module.css";

export interface CartPreviewModalPropsType {
  open: boolean;
  initialPreset: CartPresetIdType;
  brand: BrandColorsType;
  currency?: string;
  onSelectPreset: (preset: CartPresetIdType) => void;
  onClose: () => void;
}

const PRESET_OPTIONS: { id: CartPresetIdType; label: string }[] = [
  { id: "minimal", label: "Minimal" },
  { id: "bold", label: "Bold" },
  { id: "rounded", label: "Rounded" },
  { id: "editorial", label: "Editorial" },
];

export function CartPreviewModal({
  open,
  initialPreset,
  brand,
  currency = "MAD",
  onSelectPreset,
  onClose,
}: CartPreviewModalPropsType) {
  const [activePreset, setActivePreset] = useState<CartPresetIdType>(initialPreset);
  const backdropRef = useRef<HTMLDivElement>(null);

  // Sync active preset whenever initialPreset updates or modal opens
  useEffect(() => {
    setActivePreset(initialPreset);
  }, [initialPreset, open]);

  // Handle ESC key to dismiss modal
  useEffect(() => {
    if (!open) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        onClose();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [open, onClose]);

  // Handle backdrop click to close
  useEffect(() => {
    if (!open) return;
    const el = backdropRef.current;
    if (!el) return;
    const handleBackdropClick = (e: MouseEvent) => {
      if (e.target === el) {
        onClose();
      }
    };
    el.addEventListener("click", handleBackdropClick);
    return () => el.removeEventListener("click", handleBackdropClick);
  }, [open, onClose]);

  if (!open) return null;
  if (typeof document === "undefined") return null;

  return createPortal(
    <Box
      position="fixed"
      insetBlockStart="0"
      insetInlineStart="0"
      zIndex={99999}
      ref={backdropRef as any}
      className={styles.modalBackdrop}
    >
      <Transition
        animate="scale-up"
        appear
        duration={{ enter: 320, exit: 220 }}
      >
        <Box className={styles.modalContentWrapper}>
          {/* Top Control Bar: Preset Switcher + Actions */}
          <Box
            background="bg-surface"
            padding="small-300 small-200"
            borderRadius="large"
            borderColor="border-subdued"
            borderWidth="0165"
            borderStyle="solid"
          >
            <InlineStack
              alignItems="center"
              justifyContent="space-between"
              gap="base"
            >
              {/* Preset Switcher Pills */}
              <InlineStack alignItems="center" gap="small-400">
                {PRESET_OPTIONS.map((option) => {
                  const isCurrent = activePreset === option.id;
                  return (
                    <Clickable
                      key={option.id}
                      onClick={() => setActivePreset(option.id)}
                      borderRadius="base"
                    >
                      <Box
                        padding="small-400 small-200"
                        borderRadius="base"
                        background={isCurrent ? "bg-surface-strong" : "transparent"}
                      >
                        <Text
                          variant="bodySm"
                          fontWeight={isCurrent ? "bold" : "regular"}
                          color={isCurrent ? undefined : "subdued"}
                        >
                          {option.label}
                        </Text>
                      </Box>
                    </Clickable>
                  );
                })}
              </InlineStack>

              {/* Action Buttons */}
              <InlineStack alignItems="center" gap="small-300">
                <Button
                  variant="primary"
                  onClick={() => {
                    onSelectPreset(activePreset);
                    onClose();
                  }}
                >
                  Select style
